package dev.veltraph.client.combat.ghost;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import dev.veltraph.client.combat.ghost.GhostSourceWalkFrontier.Cell;
class GhostSourceLeavingLifecycleTest {
    @Test void scanRetainsOriginalCellWhenOnlyAboveStandable(){var c=new Cell(10,76,10);var a=GhostSourceLeavingLifecycle.admitted(c,v->v.y()==77);assertEquals(121,a.size());assertEquals(new Cell(5,76,5),a.getFirst());assertEquals(new Cell(15,76,15),a.getLast());assertEquals(2000,GhostSourceLeavingLifecycle.SOURCE_VISIT_LIMIT);}
    @Test void emptyCandidateFinishesParentWithoutRandom(){var l=new GhostSourceLeavingLifecycle();assertNull(l.begin(java.util.List.of(),n->{fail();return 0;}));assertEquals(GhostSourceLeavingLifecycle.State.FINISH_PARENT,l.state());}
    @Test void pathCalculatedBeforeInstantPolicyFinishes(){var l=new GhostSourceLeavingLifecycle();l.begin(java.util.List.of(new Cell(1,2,3)),n->0);assertEquals(GhostSourceLeavingLifecycle.State.CAPTURING_PATH,l.state());assertEquals(GhostSourceLeavingLifecycle.Action.FINISH_PARENT,l.captured(true,GhostSourceLeavingLifecycle.Policy.LEAVE_INSTANTLY,true,10,n->0).action());}
    @Test void sourceToolDelayIsFiveToTwentyFour(){for(int value:new int[]{0,19}){var l=new GhostSourceLeavingLifecycle();l.begin(java.util.List.of(new Cell(1,2,3)),n->0);l.captured(true,GhostSourceLeavingLifecycle.Policy.ETHERWARP_OUT,true,100,n->n==20?value:0);assertFalse(l.toolDue(104+value));assertTrue(l.toolDue(105+value));l.toolSelected();assertFalse(l.toolDue(999));}}
    @Test void queuedAndPathActiveEventsDoNotAdvanceCounter(){var l=walking();for(int i=0;i<100;i++){assertEquals(GhostSourceLeavingLifecycle.Action.NONE,l.event(true,false,false,false,1,n->0,()->0,()->true).action());assertEquals(GhostSourceLeavingLifecycle.Action.AIM_ETHER,l.event(false,true,true,true,1,n->0,()->0,()->true).action());}for(int i=1;i<9;i++)l.event(false,false,false,false,1,n->0,()->1,()->true);assertEquals(GhostSourceLeavingLifecycle.Action.SELECT_SLOT_EIGHT,l.event(false,false,false,false,1,n->0,()->0,()->true).action());}
    @Test void sourceEventLoopEndsAtThirtyEightAndFailureFinishes(){var l=walking();for(int i=0;i<37;i++)assertNotEquals(GhostSourceLeavingLifecycle.Action.FINISH_PARENT,l.event(false,false,false,false,8,n->0,()->1,()->false).action());assertEquals(GhostSourceLeavingLifecycle.Action.FINISH_PARENT,l.event(false,false,false,false,8,n->0,()->1,()->false).action());var failed=walking();failed.pathFailed();assertEquals(GhostSourceLeavingLifecycle.State.FINISH_PARENT,failed.state());}
    private static GhostSourceLeavingLifecycle walking(){var l=new GhostSourceLeavingLifecycle();l.begin(java.util.List.of(new Cell(1,2,3)),n->0);l.captured(true,GhostSourceLeavingLifecycle.Policy.ETHERWARP_OUT,true,0,n->0);return l;}
}
